fixed_code:
export function calculateBezierControlPoint(p0: { x: number; y: number }, p1: { x: number; y: number }, mid: { x: number; y: number }) {
  return {
    x: 2 * mid.x - 0.5 * (p0.x + p1.x),
    y: 2 * mid.y - 0.5 * (p0.y + p1.y),
  };
}
